import React, { useState } from "react";

export default function Registration({ onRegistered }) {
  const [name, setName] = useState("");
  const [country, setCountry] = useState("");
  const [phone, setPhone] = useState("");
  const [idProof, setIdProof] = useState("");

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!name || !country || !phone || !idProof) {
      alert("Please fill out all fields");
      return;
    }

    // Generate a simple block ID
    const blockId = "KR" + Math.floor(100000 + Math.random() * 900000);

    const touristData = {
      name,
      country,
      phone,
      idProof,
      blockId,
    };

    onRegistered(touristData);
  };

  return (
    <div
      style={{
        height: "100vh",
        background: "linear-gradient(135deg, #ffb74d, #ff6f00)",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        fontFamily: "Poppins, sans-serif",
      }}
    >
      <div
        style={{
          backgroundColor: "white",
          padding: "40px",
          borderRadius: "20px",
          boxShadow: "0px 10px 30px rgba(0,0,0,0.2)",
          textAlign: "center",
          width: "400px",
        }}
      >
        <h2 style={{ color: "#ff6f00", marginBottom: "20px" }}>
          🙏 Namaste Tourist
        </h2>

        <form onSubmit={handleSubmit}>
          <input
            type="text"
            placeholder="Full Name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            style={inputStyle}
          />
          <input
            type="text"
            placeholder="Origin Country"
            value={country}
            onChange={(e) => setCountry(e.target.value)}
            style={inputStyle}
          />
          <input
            type="tel"
            placeholder="Phone Number"
            value={phone}
            onChange={(e) => setPhone(e.target.value)}
            style={inputStyle}
          />
          <input
            type="text"
            placeholder="Aadhaar / Passport / ID Proof"
            value={idProof}
            onChange={(e) => setIdProof(e.target.value)}
            style={inputStyle}
          />

          <button
            type="submit"
            style={{
              width: "100%",
              padding: "12px",
              backgroundColor: "#ff6f00",
              color: "white",
              border: "none",
              borderRadius: "10px",
              cursor: "pointer",
              fontWeight: "bold",
              fontSize: "16px",
            }}
          >
            Register Tourist
          </button>
        </form>
      </div>
    </div>
  );
}

const inputStyle = {
  width: "100%",
  padding: "10px",
  marginBottom: "15px",
  borderRadius: "10px",
  border: "1px solid #ccc",
};
